Here is the commit message:
smb: server: fix leak of active_num_conn in
 ksmbd_tcp_new_connection()

On kthread_run() failure in ksmbd_tcp_new_connection(), the transport is
freed via free_transport(), which does not decrement active_num_conn,
leaking this counter.

Replace free_transport() with ksmbd_tcp_disconnect().

Fixes: 0d0d4680db22e ("ksmbd: add max connections parameter")
Cc: stable@vger.kernel.org
Signed-off-by: Henrique Carvalho <henrique.carvalho@suse.com>
Acked-by: Namjae Jeon <linkinjeon@kernel.org>
Signed-off-by: Steve French <stfrench@microsoft.com>

Here is the root cause:
In ksmbd_tcp_new_connection(), when kthread_run() fails after incrementing the active_num_conn counter, the cleanup function free_transport() was called. However, free_transport() only frees the transport structure without decrementing active_num_conn, causing a reference leak in the counter. The fix replaces free_transport() with ksmbd_tcp_disconnect(), which properly handles decrementing the counter.

Here is the patch:
 static void tcp_stop_kthread(struct task_struct *kthread);
 static struct interface *alloc_iface(char *ifname);
+static void ksmbd_tcp_disconnect(struct ksmbd_transport *t);

 #define KSMBD_TRANS(t)	(&(t)->transport)
  */
 static int ksmbd_tcp_new_connection(struct socket *client_sk)
 {
 	int rc = 0;
 	struct tcp_transport *t;
 	struct task_struct *handler;

 	t = alloc_transport(client_sk);
 	if (!t) {
 		sock_release(client_sk);
 		return -ENOMEM;
 	}

 #if IS_ENABLED(CONFIG_IPV6)
 	if (client_sk->sk->sk_family == AF_INET6)
 		handler = kthread_run(ksmbd_conn_handler_loop,
 				KSMBD_TRANS(t)->conn, "ksmbd:%pI6c",
 				&KSMBD_TRANS(t)->conn->inet6_addr);
 	else
 		handler = kthread_run(ksmbd_conn_handler_loop,
 				KSMBD_TRANS(t)->conn, "ksmbd:%pI4",
 				&KSMBD_TRANS(t)->conn->inet_addr);
 #else
 	handler = kthread_run(ksmbd_conn_handler_loop,
 			KSMBD_TRANS(t)->conn, "ksmbd:%pI4",
 			&KSMBD_TRANS(t)->conn->inet_addr);
 #endif
 	if (IS_ERR(handler)) {
 		pr_err("cannot start conn thread\n");
 		rc = PTR_ERR(handler);
-		free_transport(t);
+		ksmbd_tcp_disconnect(KSMBD_TRANS(t));
 	}
 	return rc;
 }



